22	// 规格示例：余额 100、费率 0，依次预览 70 与 40 —— 首项预计成功、
23	// 次项余额不足（后项必须看到前项预计成功后的余额），而不是两项都成功。
24	func TestPreviewOrderedBalance(t *testing.T) {
25		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
26		l := openOrFail(t, path)
27	
28		res, err := l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
29			intent("p1", "aa", "usdc", 70),
30			intent("p2", "aa", "usdc", 40),
31		}})
32		if err != nil {
33			t.Fatal(err)
34		}
35		if got, want := previewStatuses(res), []string{StatusSettled, StatusFunds}; strings.Join(got, ",") != strings.Join(want, ",") {
36			t.Fatalf("statuses=%v want %v", got, want)
37		}
38		if !res.DryRun {
39			t.Fatalf("preview result must carry dry_run=true")
40		}
41		r1 := res.Results[0]
42		if r1.Record == nil || r1.Record.Seq != 1 || r1.Record.Charged != 70 {
43			t.Fatalf("predicted record: %+v", r1.Record)
44		}
45		if res.Results[1].Record != nil {
46			t.Fatalf("failed preview item must not carry a record: %+v", res.Results[1])
47		}
48	}
