50	// 预计成功的新付款序号从当前最大付款序号之后连续递增；
51	// 失败、重复、冲突不消耗序号。
52	func TestPreviewSeqContinuesAndFailuresDontConsume(t *testing.T) {
53		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1_000_000}})
54		l := openOrFail(t, path)
55		// 先真实落账一笔，占住序号 1。
56		if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("seed", "aa", "usdc", 10)}}); err != nil {
57			t.Fatal(err)
58		}
59	
60		// 首项余额不足（不占序号），后项用同编号合法请求仍成功，序号接在 1 之后。
61		res, err := l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
62			intent("p", "aa", "usdc", 2_000_000), // funds
63			intent("q", "aa", "usdc", 10),        // settled -> seq 2
64			intent("p", "aa", "usdc", 10),        // settled -> seq 3（前一失败不占编号/序号）
65			intent("q", "aa", "usdc", 10),        // duplicate，不占序号
66		}})
67		if err != nil {
68			t.Fatal(err)
69		}
70		want := []string{StatusFunds, StatusSettled, StatusSettled, StatusDuplicate}
71		if got := previewStatuses(res); strings.Join(got, ",") != strings.Join(want, ",") {
72			t.Fatalf("statuses=%v want %v", got, want)
73		}
74		if res.Results[1].Record.Seq != 2 || res.Results[2].Record.Seq != 3 {
75			t.Fatalf("predicted seqs: q=%d p=%d want 2,3", res.Results[1].Record.Seq, res.Results[2].Record.Seq)
76		}
77		if dup := res.Results[3]; dup.Record == nil || dup.Record.Seq != 2 {
78			t.Fatalf("in-batch duplicate must carry the predicted original record: %+v", dup)
79		}
80	}
