82	// 预览不写账本：文件字节、余额、两类历史与预览前完全一致；
83	// 也绝不触发持久化（结果中不会出现 storage_error）。
84	type persistCounter struct{ calls int }
85	
86	func (c *persistCounter) FailNextPersist() bool { c.calls++; return false }
87	
88	func TestPreviewDoesNotWrite(t *testing.T) {
89		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
90		l := openOrFail(t, path)
91		hook := &persistCounter{}
92		SetFailHook(l, hook)
93		t.Cleanup(func() { SetFailHook(l, nil) })
94	
95		before, err := os.ReadFile(path)
96		if err != nil {
97			t.Fatal(err)
98		}
99		snapBefore, err := l.Query()
100		if err != nil {
101			t.Fatal(err)
102		}
103	
104		res, err := l.Preview(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
105			intent("p1", "aa", "usdc", 70), // 预计成功
106			intent("p2", "aa", "usdc", 90), // 预计余额不足
107			intent("p3", "zz", "usdc", 1),  // 不存在组合
108			intent("p1", "aa", "usdc", 70), // 批内重复
109		}})
110		if err != nil {
111			t.Fatal(err)
112		}
113		if got, want := previewStatuses(res), []string{
114			StatusSettled, StatusFunds, StatusFunds, StatusDuplicate,
115		}; strings.Join(got, ",") != strings.Join(want, ",") {
116			t.Fatalf("statuses=%v want %v", got, want)
117		}
118		if hook.calls != 0 {
119			t.Fatalf("preview must never persist, got %d persist calls", hook.calls)
120		}
121	
122		after, err := os.ReadFile(path)
123		if err != nil {
124			t.Fatal(err)
125		}
126		if !bytes.Equal(before, after) {
127			t.Fatalf("ledger file changed by preview")
128		}
129		snapAfter, err := l.Query()
130		if err != nil {
131			t.Fatal(err)
132		}
133		if len(snapAfter.Settlements) != len(snapBefore.Settlements) ||
134			len(snapAfter.Refunds) != len(snapBefore.Refunds) {
135			t.Fatalf("preview changed history: before=%+v after=%+v", snapBefore, snapAfter)
136		}
137		if bal, _ := l.Balance("aa", "usdc"); bal != 100 {
138			t.Fatalf("preview changed balance: %d", bal)
139		}
140	}
