230	// 失败项（参数/状态/余额/超限）不占编号：后项用同一编号改成合法可支付请求，
231	// 在同一次预览中仍可预计成功。
232	func TestPreviewFailedIDsAreReusableInBatch(t *testing.T) {
233		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
234		l := openOrFail(t, path)
235	
236		badState := intent("a", "aa", "usdc", 1)
237		badState.State = "failed"
238		zeroAmt := intent("b", "aa", "usdc", 0) // amount 不合法
239		res, err := l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
240			badState,
241			intent("a", "aa", "usdc", 10), // 同编号改为 pending：成功
242			zeroAmt,
243			intent("b", "aa", "usdc", 10),  // 同编号给出正金额：成功
244			intent("c", "aa", "usdc", 200), // 余额不足
245			intent("c", "aa", "usdc", 20),  // 同编号改小：成功
246		}})
247		if err != nil {
248			t.Fatal(err)
249		}
250		want := []string{
251			StatusState, StatusSettled,
252			StatusInvalid, StatusSettled,
253			StatusFunds, StatusSettled,
254		}
255		if got := previewStatuses(res); strings.Join(got, ",") != strings.Join(want, ",") {
256			t.Fatalf("statuses=%v want %v", got, want)
257		}
258		// 三个成功项序号连续 1、2、3（失败项不占序号）。
259		for i, idx := range []int{1, 3, 5} {
260			if res.Results[idx].Record.Seq != int64(i+1) {
261				t.Fatalf("item %d seq=%d want %d", idx, res.Results[idx].Record.Seq, i+1)
262			}
263		}
264	}
